// Parsear guión generado
const prevData = $('📊 Parsear Análisis').first().json;
const aiRaw = $input.first().json;

let script;
try {
  let text = aiRaw?.text || aiRaw?.output || aiRaw?.response || JSON.stringify(aiRaw);
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  script = (typeof text === 'object') ? text : JSON.parse(text);
} catch(e) {
  script = {
    guion: `Hola, soy ${prevData.avatar.name}. Hoy quiero presentarte algo increíble: ${prevData.analysis.producto}. Este producto está diseñado para ${prevData.analysis.publico} que buscan lo mejor. ${prevData.analysis.beneficios.join('. ')}. No te quedes sin el tuyo, te aseguro que va a cambiar tu experiencia por completo.`,
    duracionEstimada: '30 segundos',
    hookInicial: 'Hoy quiero presentarte algo increíble',
    callToAction: 'No te quedes sin el tuyo'
  };
}

return [{
  json: {
    ...prevData,
    script
  }
}];

// Preparar datos para D-ID o HeyGen
const prevData = $('📝 Parsear Guión').first().json;
const audioData = $input.first();

// Obtener audio en base64 si está disponible
let audioBase64 = '';
try {
  if (audioData.binary && audioData.binary.data) {
    audioBase64 = audioData.binary.data.data; // base64
  }
} catch(e) {
  console.log('Audio no disponible en binario, se usará TTS del servicio de avatar');
}

return [{
  json: {
    ...prevData,
    audioBase64,
    audioAvailable: !!audioBase64
  }
}];

// Polling D-ID hasta que el video esté listo
const talkId = $input.first().json.id;
const maxAttempts = 30;
let attempt = 0;
let videoUrl = null;

while (attempt < maxAttempts) {
  attempt++;

  const response = await fetch(`https://api.d-id.com/talks/${talkId}`, {
    headers: {
      'Authorization': `Basic ${$env.DID_API_KEY}`,
      'Content-Type': 'application/json'
    }
  });

  const data = await response.json();

  if (data.status === 'done' && data.result_url) {
    videoUrl = data.result_url;
    break;
  } else if (data.status === 'error') {
    throw new Error(`D-ID error: ${data.error?.description || 'Unknown'}`);
  }

  // Esperar 5 segundos entre polls
  await new Promise(r => setTimeout(r, 5000));
}

if (!videoUrl) {
  throw new Error('Timeout esperando video de D-ID');
}

return [{ json: { videoUrl, service: 'd-id', talkId } }];

// Polling HeyGen hasta que el video esté listo
const videoId = $input.first().json.data?.video_id;
const maxAttempts = 60;
let attempt = 0;
let videoUrl = null;

while (attempt < maxAttempts) {
  attempt++;

  const response = await fetch(`https://api.heygen.com/v1/video_status.get?video_id=${videoId}`, {
    headers: {
      'X-Api-Key': $env.HEYGEN_API_KEY,
      'Content-Type': 'application/json'
    }
  });

  const data = await response.json();

  if (data.data?.status === 'completed' && data.data?.video_url) {
    videoUrl = data.data.video_url;
    break;
  } else if (data.data?.status === 'failed') {
    throw new Error(`HeyGen error: ${data.data?.error || 'Unknown'}`);
  }

  await new Promise(r => setTimeout(r, 5000));
}

if (!videoUrl) {
  throw new Error('Timeout esperando video de HeyGen');
}

return [{ json: { videoUrl, service: 'heygen', videoId } }];

// Merge final: capturar el videoUrl sin importar qué rama (D-ID o HeyGen) lo generó
const allInputs = $input.all();
const videoInput = allInputs.find(item => item.json.videoUrl)?.json || {};
const originalData = $("📝 Parsear Guión").first().json;

return [{
  json: {
    jobId: originalData.jobId,
    videoUrl: videoInput.videoUrl || "No URL found",
    service: videoInput.service || "unknown",
    producto: originalData.analysis.producto,
    avatar: originalData.avatar.name,
    estilo: originalData.styleKey,
    guion: originalData.script.guion,
    duracion: originalData.script.duracionEstimada,
    timestamp: new Date().toISOString(),
    status: "completed"
  }
}];
